//! #487: each newly enforced row consumes a frame written by the reference recorder.
#![cfg(feature = "wallet")]
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // #134: tests

#[allow(dead_code)]
#[path = "support/fixtures/wallet_json.rs"]
mod wallet_json;

use async_trait::async_trait;
use bsv_rs::wallet::wire::{WalletWire, WalletWireTransceiver, WireReader};
use bsv_rs::Error;
use serde::Deserialize;
use serde_json::Value;
use wallet_json::FixtureJson;

#[derive(Deserialize)]
struct Recording {
    source: String,
    node: String,
    rows: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    row: u32,
    call: String,
    args: Value,
    request_hex: Option<String>,
    response_hex: Option<String>,
    response_parts: Option<Vec<Part>>,
    reference: Value,
    #[serde(default)]
    argument_side: bool,
}

#[derive(Deserialize)]
struct Part {
    hex: String,
    repeat: usize,
}

struct RecordedWire {
    response: Vec<u8>,
    request: Option<Vec<u8>>,
    forbid_transmit: bool,
}

#[async_trait]
impl WalletWire for RecordedWire {
    async fn transmit_to_wallet(&self, request: &[u8]) -> Result<Vec<u8>, Error> {
        assert!(
            !self.forbid_transmit,
            "an argument refusal must not transmit a request"
        );
        if let Some(expected) = &self.request {
            assert_request(request, expected);
        }
        Ok(self.response.clone())
    }
}

fn assert_request(actual: &[u8], expected: &[u8]) {
    if actual == expected {
        return;
    }
    // signAction's pre-existing HashMap writer has no stable iteration order.
    // Compare that map by its entries and every other request byte exactly.
    let read = |bytes: &[u8]| {
        let mut reader = WireReader::new(bytes);
        assert_eq!(reader.read_u8().unwrap(), 2);
        let length = reader.read_u8().unwrap() as usize;
        let originator = reader.read_bytes(length).unwrap().to_vec();
        let spends = reader.read_sign_action_spends().unwrap();
        (
            originator,
            serde_json::to_value(spends).unwrap(),
            reader.read_remaining().to_vec(),
        )
    };
    assert_eq!(
        read(actual),
        read(expected),
        "the request bytes must remain unchanged"
    );
}

async fn invoke(case: &Case) -> Result<(), Error> {
    let response = match &case.response_hex {
        Some(hex) => hex::decode(hex).unwrap(),
        None => case
            .response_parts
            .as_ref()
            .unwrap()
            .iter()
            .flat_map(|part| hex::decode(&part.hex).unwrap().repeat(part.repeat))
            .collect(),
    };
    let wallet = WalletWireTransceiver::new(RecordedWire {
        response,
        request: case.request_hex.as_ref().map(|s| hex::decode(s).unwrap()),
        forbid_transmit: case.argument_side,
    });
    macro_rules! call {
        ($name:ident) => {
            wallet
                .$name(
                    FixtureJson::from_fixture(case.args.clone()),
                    Some("fixtures.invalid"),
                )
                .await
                .map(|_| ())
        };
    }
    match case.call.as_str() {
        "createAction" => call!(create_action),
        "signAction" => call!(sign_action),
        "listOutputs" => call!(list_outputs),
        "createSignature" => call!(create_signature),
        "revealCounterpartyKeyLinkage" => call!(reveal_counterparty_key_linkage),
        "revealSpecificKeyLinkage" => call!(reveal_specific_key_linkage),
        "acquireCertificate" => call!(acquire_certificate),
        "listCertificates" => call!(list_certificates),
        "proveCertificate" => call!(prove_certificate),
        other => panic!("unrecorded call {other}"),
    }
}

async fn check(row: u32) {
    let recording: Recording = serde_json::from_str(RECORDING).unwrap();
    assert_eq!(recording.source, "ts-stack@edf6e03");
    assert_eq!(recording.node, "v22.18.0");
    let cases: Vec<_> = recording.rows.iter().filter(|c| c.row == row).collect();
    assert!(!cases.is_empty(), "row {row} has no recorded frames");
    if row == 0 {
        assert_eq!(cases.len(), 56);
        assert_eq!(
            cases
                .iter()
                .filter(|c| c.reference["accepted"] == true)
                .count(),
            48
        );
    }
    let mut mismatches = Vec::new();
    for case in &cases {
        if matches!(
            case.name.as_str(),
            "acquireCertificate_certificate_off_curve" | "listCertificates_certificate_off_curve"
        ) {
            continue; // Pinned separately below: the stated #183 point-decoding difference.
        }
        let actual = invoke(case).await;
        let matches = match &actual {
            Ok(()) => case.reference["accepted"] == true,
            Err(Error::WalletError(words)) => {
                case.reference["code"].is_null()
                    && case.reference["message"].as_str() == Some(words)
            }
            Err(Error::WalletRefusal { class, message }) => {
                case.reference["code"].as_u64() == class.wire_code().map(u64::from)
                    && case.reference["message"].as_str() == Some(message)
            }
            _ => false,
        };
        if !matches {
            mismatches.push(format!(
                "{}: {actual:?}; recorded {}",
                case.name, case.reference
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "row {row}: {} frames\n{}",
        cases.len(),
        mismatches.join("\n")
    );
}

macro_rules! row {
    ($name:ident, $number:literal) => {
        #[tokio::test]
        async fn $name() {
            check($number).await;
        }
    };
}

row!(row_00_accepting_frames_and_refusals_487, 0);

async fn off_curve(name: &str, reference_words: &str) {
    let recording: Recording = serde_json::from_str(RECORDING).unwrap();
    let case = recording.rows.iter().find(|c| c.name == name).unwrap();
    assert!(case
        .response_hex
        .as_ref()
        .unwrap()
        .contains(&format!("02{}", "ff".repeat(32))));
    assert_eq!(
        case.reference,
        serde_json::json!({"code": null, "message": reference_words})
    );
    assert_eq!(
        invoke(case).await,
        Err(Error::WalletError(
            "Invalid certificate subject: expected a compressed secp256k1 public key".into()
        )),
        "{name}: x = 2^256 - 1, the stated #183 difference"
    );
}

#[tokio::test]
async fn acquire_certificate_off_curve_is_the_stated_183_difference() {
    off_curve("acquireCertificate_certificate_off_curve",
        "Invalid acquireCertificate result certificate: expected a canonical signed wallet certificate").await;
}

#[tokio::test]
async fn list_certificates_off_curve_is_the_stated_183_difference() {
    off_curve("listCertificates_certificate_off_curve",
        "Invalid listCertificates result certificates[0]: expected a canonical signed wallet certificate").await;
}

async fn argument_refusal(name: &str) {
    let recording: Recording = serde_json::from_str(RECORDING).unwrap();
    let case = recording
        .rows
        .iter()
        .find(|case| case.name == name)
        .unwrap();
    assert!(case.argument_side);
    assert_eq!(case.reference["code"], 6);
    assert_eq!(
        invoke(case).await,
        Err(Error::WalletRefusal {
            class: bsv_rs::WalletRefusalClass::InvalidParameter,
            message: case.reference["message"].as_str().unwrap().into(),
        })
    );
}

